content:
@layer components {
  .shelf-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
    gap: var(--shelf-space-md);
    margin: 0 auto;
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    box-shadow: var(--shelf-shadow-md);
    margin-top: var(--shelf-space-md);
  }
}

@layer components {
  .chip-bar {
    display: flex;
    gap: var(--shelf-space-sm);
    padding: var(--shelf-space-sm) var(--shelf-space-md);
    background-color: var(--shelf-bgColor-default);
  }
}

@layer components {
  .app {
    display: flex;
    flex-direction: column;
    min-block-size: 100dvh;
    margin: 0 auto;
    max-inline-size: 80rem;
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    inline-size: min(24rem, 90vw);
    background-color: var(--shelf-bgColor-raised);
    margin-inline: 0;
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    margin-block: var(--shelf-space-sm);
  }
}
